      "ဝိစာရ အၚ်္ဂဇျာန်၊ မၞုံပဓါန်လၞိန်ဗပိန်ကၠေံဝိစိကိစ္ဆာနိဝဵုတုဲ မသပေါတ်တဴအရီုဓဝ်သမ္ပယုတ်ဝိတက်မပ္တိုန်လဝ်ဂှ်ကီု",
