      "အတိုင် သၞောတ်ဝ် ရူပဗေဒ ဓမ္မတာ မ္ဂး၊ ဒြပ်ဝတ္ထု လဵု မွဲ လေဝ် ဍေံ ဒြေပ် ပြဟ် နူ ဇြဟတ် လျး ပ္ဍဲ အာကာသ ဟွံမာန် ရ",
