      "ပ္ဍဲခေတ်လၟုဟ်မ္ဂး ကြက္ကဒိန်ဏအ် ဒှ်သၞောတ်စၟတ်သမ္တီအခိင် သုတေသန ကေုာံ ပရေင်ကမၠောန်သၠုင်အိုတ် ပ္ဍဲကေင်ကာဂၠးကဝ်ရ",
      "နကဵုဘာသာမန်လေဝ် ဝဳကဳပဳဒဳယာ နွံတုဲ သွက်ဂွံချူ ပရူပရာ မဆေင် ကုဂကူမန် နာနာသာ်ဂှ် ဒှ် ကိရိယာမွဲ မနွံကဵု သၠုင်ကျာ",
      "သိုင်ခၞံဘာ မၞုံကဵုပရိုက်ဘဲ ဟွံမွဲကဵုဥပစာမွဲသ္ပဝ်ကွဳအိုတ်မ္ဂး၊ ကုခမဳသိုင်ခၞံဘာဂမၠိုင် ဒးအာပတ်ဒုက္ကဋ် ၜါလစုတ်ရ",
      "အဵုလၟာဂၞဴ ညံၚ်စဴရကောန်၊ ဒိုဟ်ဒးကၠဗြန် ဗြုပၠန်ကဵုယာဲ၊ မိကော်စလာၚ် ဟွံမိၚ်ပါၚ်နာဲ၊ ဓဇန်လောန်ကာဲ ကဵုယာဲသွံကောန်",
      "ကောန်ဇာတ်ဇကု ဒးဒှ် ဒၟံၚ်ဍိက်ပၠက်ညးတၞဟ်ဂှ် ဂွံဆဵုညာတ်ကေတ်တုဲ မိပ်သၠောၚ်ဒၟံၚ် ပ္ဍဲကောန် စိုတ်တေံ မာန်ဒၟံၚ်ကီုဟာ",
      "ထပိုက်အရက်ဍာ်ဂျိဟွံမာန်တုဲ မၞိဟ်ဗၜူကြအ်ချိုတ်အာတံဂှ် ပါ်ကရေတ်ထိုၚ်စၞညးတံမ္ဂး အုဲလီုဗစံက်ယောမ်မံၚ်ဂှ်ဂွံဆဵုတဴရ",
      "ညးပတှ်ေကေတ် ကောန်မၞိဟ်တအ်ဂှ် မပ နကဵုနဲနာနာသာ် ပ္ဍဲအခိင်ကာလ ညးတအ် မနွံကဵု ဂကောံ ကဵု ပ္ဍဲကာလ ညးတအ် မနွံညးမွဲဓဝ်",
      "ပရေင်သုင်စောဲ သင်္ကေတ သွက်ဂွံ စၟတ်သမ္တီ တၠဒြပ် ဟွံသေင်မ္ဂး ညးမကၠောန်ပ္တိတ်ဂှ် စကတဵုဒှ်လဝ် နူကဵု ခေတ်တမၠာတေအ်ရ",
      "နကဵု နာဲဗညာအံင်လေဝ် လုပ်ကေတ်တာလျိုင် နဒဒှ် သကိုပ်အေဝ်ဒဳတာ ပ္ဍဲကဵု ဌာန်ပရိုင်မန် မဒှ်ဌာန်ပရိုင်အပ္ဍဲသၞောဝ်ကီုရ",
      "ဒၞာဲမစကာ ပညာစိတ္တဗေဒဂၠိုင်အိုတ်ဂှ် ဒှ် ပ္ဍဲဒၞာဲမလွဳလွတ်၊ လွဳယဲ၊ အရာမကဵုကသပ်၊ ကေုာံ ပရေင်ဗတောန်လိက် ပ္ဍဲဘာတအ်ရ",
      "ဍုင်ဒေန်မက်ဂှ် ဂွံစၟတ်သမ္တီလဝ် ပၞောဝ်ကဵုဍုင်ပရေင်မၞိဟ် ကေုာံ ပရေင်ပိုန်ဒြပ် မဇၞော်မောဝ်အိုတ်ဂှ် ပါလုပ်မွဲကီုရ",
      "ပ္ဍဲအခိၚ်ဂှ် တဳလပိုဉ်အာဿဇိ ဂေတ်ဂ္ၚေၚ်တၞဟ်နပိဏ္ဍပါတ် ပ္ဍဲဍုၚ်ရာဇဂြိုဟ်တုဲ ဂိုၚ်ကေတ်ပိဏ္ဍပါတ်တုဲမ္ဂး က္ညစ္ဍးအာရ",
      "သၞောဝ် ဒြဟတ်ဓရိုတ်တံင် နယူတန် ဏအ်ရ ဒှ်သွဟ် သွက်သၞောဝ်ကပ်ပလာတုဲ၊ ပသောင်ကလးကဵု ပရေင်အံင်ဇၞး အလုံစက္ကဝါမာန်ကၠုင်ရ",
      "ပၠိုပ်ဂိုဟ် ကျာ်ဇၞော်အစာဘဒ္ဒန္တသဳလာစာရ ဘာဗဂေါပရိယတ္တိ ဍုင်မတ်မလီု ဂကောံကဵုပူဇဴပ္ကဴလၞီ ကေုာံ ဝတ္ထုဒါန် ၁၆ ကိုဋ်",
      "ရုပ်ကလာပ် နာဲဆာန်အံင်ဂှ် ကောန်ဇာတ်တအ် ကေတ်ဖျဴနင်ကွာန်တုဲ စံင်ဇွ ပ္ဍဲသုသာန် ကွာန်မုဟ်ဒုန် ပ္ဍဲ ဂိတုမာတ် ၃၁ ဂှ်ရ",
      "ပ္ဍဲအခိၚ်ဂှ် သၟိၚ်ဗိမ္ဗိသာရ မၞုံသေနိယ တၠညးမဂဓရး မိက်ကဵုသိုၚ်ခၞံ ပြာသာဒ် မလံက်လေတ်အၚ်္ဂဒဵုတိကမၠေတ် တၞဟ်နဖဵုသၚ်ရ",
      "ပ္ဍဲကာလဂှ် နာဲမောင်သိန်း ပ္ကောံဂွံလဝ် သေနာတ်ရာ်ဖေဝ် ၄ ဇကိုအ်၊ သေနာတ်ပေစ္စတဝ် ၁ ဇကိုအ်၊ သေနာတ်တေန်ဂါန် ၁ ဇကိုအ်",
      "လိက်ပညာပၞာန်ဏအ်ဂှ် ဗွဲကြဴဏအ် စကာကၠုင် ဆပ္ဍဲပၞာန်မွဲဓဝ်ဟွံသေင် သီုကဵု ပ္ဍဲပရေင်ဍုင်ချာန်၊ ပရေင်ပိုန်ဒြပ်တအ်ကီုရ",
      "ဖေဖဝ်ဝါရဳ ၁၀ ဂှ် နူကဵု သမဂ္ဂသၟာကမၠောန်တအ် ဒစဵုဒစး လတူတၠကမၠောန် မဓရတ် ကောန်ကမၠောန် ကုညးမပါလုပ် ပ္ဍဲကာမ်ပိန်တအ်ရ",
      "ဟိုတ်ဂှ်ရ နကဵု ဒပ်ပၞာန်အာတ်မိက်ကၠုင် ညံင်ဂွံပသောင်ကလးကဵုကီုလေဝ် နကဵု ဗော်အေန်အေဝ်ဒဳ ဟွံဒုင်တဲ ဟွံပသောင်ကလးကဵုရ",
      "ဂၞကျာ် သၟိင်ရာမ ပထမ ဂှ် အမာရိနဒြာဂှ် ဒှ်ကောန်သေဋ္ဌဳဂကူမန် မပြံင်လုပ် ဍုင်သေံ နူကဵုဍုင်မန် နူအခိင်ကိုပ်ကၠာတေအ်ရ",
      "ညးပါ်ပါဲတအ် တော်ကေတ်မ္ဂး ညံင်ရဴဒေသတၞဟ်တအ်ကီု ပ္ဍဲပွိုင်ဍုင်ပံင်ဝွံလေဝ် နကဵုကမ္မရှေန်မာဲဂှ် ဖန်လီလာန်လဝ်မာဲကီုရ",
      "နကဵု နဲဏအ်ဂှ် မၞိဟ်တြုဟ်ဂှ် ပၠုပ်စုတ် အင်္ဂဇာတ်ဇကု အပ္ဍဲ ယောနိမၞိဟ်ဗြဴ တုဲ ကရိုဟ်ပတိတ် ဍာ်သုက် မနွံကဵု စၟသုက်ရ",
