      "ဍုင် မက်သဳဒဝ်နဳယျာ သၟဝ်ကျာ ဝွံ နွံ ကု သယံဇာတ ဓါတ်သတ္တု သဘာဝ ဗွဲမဂၠိုင် မဒှ် အရာ အဓိက သွက် ပရေင်ပိုန်ဒြပ် ဍုင် ရ",
      "ၜိုန်ရ လၟိဟ် မၞိဟ် ချိုတ် သၠုၚ် ကီု လေဝ်، စဵုကဵု လၟုဟ် မ္ဂး ဍေံ ကၠောအ်က္ဍ လောဲလောဲ လတူ ညးဍုၚ်ကွာန် ဟွံမာန် ပုဟ်",
      "ဟိုတ်ဂှ်ရ ရုင်ဒမျိုင် ဏအ် ဍေံ ဒှ် ရုင်ဒမျိုင် မကလိဂွံ သြန် ဂၠိုၚ် အိုတ် မရနုက်ကဵု ၜါ ပ္ဍဲ ဝင် ဍုၚ် ကိုဝ်ရဳယျာ ရ",
      "ပရေင်ပိုန်ဒြပ် အဓိက ပ္ဍဲ ရးတၞင်သဳ ဂှ် တန်တဴဒၟံင် လ္တူ သယံဇာတ သဘာဝ မပ္တံကဵု တိဍာ်၊ ဓါတ်သတ္တု ကေုာံ ကပေါတ်ၜဳ တအ်ရ",
      "ယဝ်ရ မၞိဟ် နူ မ္ၚး ပၠောပ် နင် လိက် သၟာန် တရုပ် မ္ဂး၊ အဲ ရံင် ပြကိုဟ် တုဲ ကလေင် ချူ သွဟ် တရုပ် ဍာံဍာံ ပြပြ မာန်ရ",
      "ကုခမဳမဂွံပြဘိုဂ်ဂဥုဲမကဵုဒါန် ကုခမဳဂိယဲဂမၠိုၚ် အဲဍိက်ဂှ် ယဲလေဝ် ကြက်ဟွံဂၠိုၚ်တိုန်ရ၊ ပွမဒးချိုတ်လေဝ် ကြက်ဟွံဒှ်ရ",
      "ဂၞန် လက် ဝွံ ဍေံ ဒှ် သင်္ကေတ အဓိက သွက် ပရေင် ဂၠိုင်ဂၠင် ဗွဲမလောန် ကေုာံ သင်္ကေတ အနန္တ ပ္ဍဲ ယေန်သၞာင် တြေံ တအ် ရ",
      "ယွံခမဳတအ် ခမဳကၠောန်ၜိုတ်ဥပကာညးယဲ မဍိုက်ပေၚ်တဴကေုာံအၚ်္ဂဂမၠိုၚ်မသုန်ပြကာဂှ် ဟွံထေက်ကဵု တၞဟ်နကၠောန်ၜိုတ်ဥပကာညးယဲရ",
      "တုဲပၠန် နဲကဲလ္ၚဵုဂှ် သွက်မၞိဟ်လ္ၚဵု ဒုင်စသိုင်ခိုဟ်ကီုလေဝ် သွက်မၞိဟ်သအာင် ဟွံဒှ်အရာမဒုင်စသိုင်ခိုဟ်လေဝ် နွံကီုရ",
      "သတ်ဒူရေန်နူကဵုဒေသရးမန်တံ တိတ်မံၚ်ဗွဲမဂၠိုၚ်ကီု ဟီုမာန်ကီုလေဝ် အခိၚ်လၟုဟ်မ္ဂး ပ္ဍဲကဵုဗွဝ်ဖျာဂှ် မုက်မတ်ဟွံကျေဝ်ရ",
      "ကပေါတ်ကွတ်စက်ကဆံင်သမၠုင် ဗီုကဵု သမာတ်ဖုန်၊ ကောန်ပျူတာ ကေုာံ စက်ဍောတ်တ် ကွတ်တဲသၠုင်သၠုင်တအ် ဒးစကာ ဓါတ်စဏအ်ဖအိုတ်ရ",
      "ပ္ဍဲၜိုပ်ဂှ်တုန်လေဝ် မၞိက်ရတ်မွဲ ဍေံၚိတ်လဝ် ယြဴကာလထာန်ဒၟံၚ်မွဲ ဍေံသအာဂၚေၚ် မ္ဂး ထာန်ဂှ် မိပ်သ္ၚိပ် ရာၚ်ဆာဲအာဟေၚ်",
      "ညး အာတ်မိက် ညံၚ် ဂွံ စၟတ်သမ္တီ တ္ၚဲ ၂၁ ဖေဖဝ်ဝါရဳ နဒဒှ် တ္ၚဲ အရေဝ် မိ အလုံ ဂၠးတိ သွက်ဂွံ မၚ်မဲ အရေဝ် ဘာသာ ဂၠးတိ ရ",
      "ကာလညးတေအ် သီဂွံဒေသဂှ်တုဲ ဝါဟေဒ် ခပူပထောင်ဇၞော် ပ္ဍဲက္ဍိုပ်ကျာ်တအ်တုဲ ပ္ဍဲဂှ် ညးစုတ် ဒါင်နမာက်တုဲ ခတိုဟ်ပလီုထောအ်ရ",
      "ပ္ဍဲအခိင်အင်္ဂဇာတ် ကြံင်မ္ၚိုဟ်တေင်ကၠုင် ဟိုတ်နူရာဂ မ္ဂးဂှ် ကုညးရာဂရာန်ကိုတ်တဴဂှ် တၞဟ်နသ္ပအင်္ဂဇာတ် ဒှ်ဒၟံင်ဒတုဲရ",
      "ပါဲနူဂှ်တုဲ ပ္ဍဲ ဂကောံသၟတ်မန်ဂှ်လေဝ် ချဳဓရာင်ကၠုင်လဝ်တုဲ ညံင် တ္ၚဲသၟတ်မန် ဂွံဒှ်ကၠုင်ဂှ် ပါလုပ် ချဳဓရာင်ကၠုင်လဝ်ရ",
      "ပ္ဍဲသ္ၚာမဂပ်ဝ်ကဵုဒါန် ဗွဲမဃရက်ဂဗက်ဟွံသေၚ်ဂှ် မၞုံကဵုစၟတ်သမ္တီ သ္ၚာမဂပ်ဝ်ကဵုဒါန် ဗွဲမဃရက်ဂဗက်မ္ဂး၊ ဒးအာပတ်ဒုက္ကဋ်ရ",
      "ယွံခမဳတအ် မွဲဂကူပၠန်တုန် သမဏဗြာဟ္မဏဂမၠိုၚ်လ္ၚဵု ဂယိုၚ်လမျီုမှာရာအိုတ်ရ၊ ဟွံဝေၚ်ပါဲကၠေံ နူပွမဂယိုၚ်လမျီုမှာရာအိုတ်ရ",
      "ဝင် ဏအ် ထ္ၜးကဵု ဒဒှ်ရ ပရေင်ချဳဓရာင် ဝွံ ဒှ် လွဟ် ညးဍုင်ကွာန် မဟွံမဲ ကဵု အာဏာ တအ် သွက်ဂွံ တဝ်စၞေဟ် ကု သၟိင်တၠ တအ် ရ",
      "ပါဲနူဂှ်တုဲ ဇၟာပ်ကောန်ဂကူ မပတဴ ပ္ဍဲ သဟရးဗၟာတအ်ဂှ် ညံင်ဂကူညးတအ် ဟွံဂွံကၠေအ်ကၠက်အာ၊ သွက်ဂွံ ဒက်ပတန်သၞောတ်ဒဳမဝ်ကရေသဳရ",
      "ပ္ဍဲအဃောအခိၚ်ဂှ် နန္ဒာ နန္ဒဝတဳ သုန္ဒရဳနန္ဒာ ထုလ္လနန္ဒာ ၝဲဒေံဂမၠိုၚ်ပန်တၠဝွံ ဒှ်ခမဳဗြဴ ပ္ဍဲဇရေၚ်ခမဳဗြဴဂမၠိုၚ်အိုတ်ရ",
      "ၜိုန်ရ သၞောဝ် ဂၠးတိ နွံ ကီုလေဝ်၊ ဍုင် ဗွဲမဂၠိုင် ဆက် တန်တဴ ဟွံမာန် ပဍိုက်ပေင် အခေါင် ဏအ် သွက် ကောန်ဍုင် ညးတအ် ဏီ ရ",
