      "မၞိဟ်ပြာကတ် ပ္ဍဲကဵု ဒပ်ဂှ်တှ်ေ နာဲအံင်ယှုင် ရဲဍုင်ရေဝ်ဂှ် ဒှ်အစာဂဥုဲ၊ နာဲဘရဏ ရဲကြေဝ်ဏာဂှ် ဒှ်သွာင်စန်ဒက် ညးဍုင်ကွာန်",
