      "ကာဗောန်ဒါင်အံက်သိုက် ဝွံ ဒှ် ဓါတ် မကိစ္စဇၞော် အိုတ် မွဲ သွက် ပရေင်ဂျိုင်တန်တဴ သဘာဝ သတ္တဝါ ကေုာံ တၞံဆု လတူ ဂၠးတိ ဏအ် ရ",
      "တင်အဓိက လညာတ်ဟွံတုပ်ရေင်သကအ်ဂှ် ပဝ်ဂူဂိန်ဂှ် ဓဇက်ရုပ် နကဵုတင်မသမ္တီလဝ် အရာမဒှ်ကၠုင်တုဲ ဆက်ဓဇက်အာ ကေုာံ ဖန်ဗဒှ်ပတိုန်ရ",
