      "ဆဂး၊ ပ္ဍဲ အခိင် တုပ် ဂှ်၊ အလဵုအသဳ တအ် လေဝ် စကာ နည်းပညာ တအ် ဏအ် သွက်ဂွံ လ္ၚတ် သ္ၚေဝ်ဂၠေပ် ကေုာံ ဍဵုဍိုက် ပရေင်ချဳဓရာင် တအ် ဗွဲမလောဲသွာ မာန် ကီု ရ",
      "လိက်ပရေင် ဏအ်ဝွံ သ္ၚေဝ်ဂၠေပ် လဝ် ပရူပရာ အစာချူလိက် နကဵု လညာတ် ဝင်၊ ဂကူ ကဏ္ဍ၊ လၟေင် ကမၠောန်၊ ကေုာံ ဖဵုသက်ရောက် လတူ ဂကောံမၞိဟ် ခေတ်တၟိ ဗွဲမလှဲလး ရ",
      "ပါဲနူဂှ်တုဲ ကမၠောန်မဆေင်ကဵု မန် ပ္ဍဲဗွိုင်အလဵုအသဳ မပ္တံကဵု တ္ၚဲတွဵုရးဍုင်မန်တအ်ဂှ်လေဝ် ကေင်ကေတ်ကၠုင်တာလျိုင် ပ္ဍဲဂကောံသဘာပတိ သၞာံမဂၠိုင်ကဵုအလန်ရ",
