      "ဂကောံဏံ ဂွံက္တဵုဒှ်ကၠုၚ်ဂှ် ဟိုတ်နူဆန္ဒမၞိဟ်မွဲ ပူဂိုလ်မွဲဟွံသေၚ် ဟိုတ်နူဆန္ဒဂကောံ ဆန္ဒသၚ်တအ်တုဲ က္တဵုဒှ်ကၠုၚ်ရောၚ် ကဵုဂွံစှေ်စိုတ် သီုညးဖအိုတ်ညိ",
      "လၟုဟ် မ္ဂး ဍုင်အင်ဝ ဝွံ သှ်ေၜိုတ် ဆ ပရေင် အာဲကၟာဲ ဝင် တြေံ ကေုာံ ဌာန် ညးဍုင်ကွာန် ဂမၠိုင် တန်တဴ တုဲ ဒှ် ဒၞာဲ ဌာန် လ္ၚတ် ဝင် ဍုင်ဗၟာ မပြာကတ် မွဲ ရ",
