      "ပရေင်သၞာတ်ဂှ် ဒှ်ပြသၞာဇၞော် မဒးစွံအာရီုလဝ် နကဵုမတ်သိၚ်္ဂဵုတုဲ ဒးဖျေဟ်သ္ဂုတ်သွာတ် နကဵုပရေင်ဓရီုကျာ်သဳကၠဳ မတုပ်သၟဟ် နကဵုစိုတ်ဍာံ သွက်ဂွံဂွံသၟဟ်နသက်ရ",
      "ပ္ဍဲကဵုဝင်ဂှ် စၟတ်သမ္တီလဝ် သၟိင်မန်တအ် မဒက်ပ္တန်လဝ် ဍုင်ဇၞော်တအ် နကဵုယေန်သၞာင် မဇၞော်မောဝ်တဴ ဗွဲမလောန်တုဲ ဒှ်သက်သဳ မထ္ၜးကဵု ဒဒှ်ဂကူမန် မနွံကဵုပညာရ",
      "ဂၠးတိဏံ ပရေင်ပံင်ကောံညးဍုင်ကွာန်ဂှ် ကိစ္စဇၞော် သွက်ဂွံဒ္ၚဳဂွံ ပရေင်ၜိုဟ်သြိုဟ် ကေုာံ ပရေင်ဇၞော်မောဝ် ပ္ဍဲကဵုဒေသနာနာ နကဵုပရေင်ပံင်တောဲ မတုပ်သၟဟ်ရ",
      "ပ္ဍဲကဵုအရာမကၠောန်ကမၠောန်ဂှ် ဒးနွံကဵု ပရေင်လ္ၚတ် ကေုာံ ပရေင်စမ်ၜတ် မခိုင်ကၠိုက်တုဲ ဒးဖန်ဗဒှ် နဲကဲတၟိတအ် သွက်ဂွံတုဲဒှ် နကဵုလၟေင် မစၟတ်သမ္တီလဝ်ရ",
      "ယွံခမဳတအ် ပရေင်မင်မဲသဳလဂှ် ဒှ်တၞဟ်ခြာ နူကဵု ပရေင်ပတှ်ေသၟးတုဲ ဒးဒ္ဂေတ်မၚ်မွဲလဝ် သဳလ နကဵုမတ်သိၚ်္ဂဵု ဗွဲမစၟတ် သွက်ဂွံဒှ်ဒတုဲရ",
